<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');if($_SERVER['REQUEST_METHOD']==='POST'){$q=$db->prepare('INSERT INTO marketing_content(title,slug,content_type,meta_title,meta_description,keywords,status,published_at) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE title=VALUES(title),content_type=VALUES(content_type),meta_title=VALUES(meta_title),meta_description=VALUES(meta_description),keywords=VALUES(keywords),status=VALUES(status),published_at=VALUES(published_at)');$q->execute([trim($_POST['title']),trim($_POST['slug']),$_POST['content_type'],trim($_POST['meta_title']??''),trim($_POST['meta_description']??''),trim($_POST['keywords']??''),$_POST['status'],$_POST['status']==='published'?date('Y-m-d H:i:s'):null]);header('Location: marketing-content.php');exit;}$rows=$db->query('SELECT * FROM marketing_content ORDER BY updated_at DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Marketing Content & SEO</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Content & SEO</h1><form method="post" class="card card-body mb-4 row g-2"><div class="col-md-5"><input class="form-control" name="title" placeholder="Content title" required></div><div class="col-md-4"><input class="form-control" name="slug" placeholder="slug" required></div><div class="col-md-3"><select class="form-select" name="content_type"><option>blog</option><option>landing_page</option><option>case_study</option><option>service_page</option></select></div><div class="col-md-6"><input class="form-control" name="meta_title" placeholder="Meta title"></div><div class="col-md-6"><input class="form-control" name="keywords" placeholder="Keywords"></div><div class="col-12"><textarea class="form-control" name="meta_description" placeholder="Meta description"></textarea></div><div class="col-md-3"><select class="form-select" name="status"><option>draft</option><option>published</option><option>archived</option></select></div><div class="col-12"><button class="btn btn-dark">Save SEO Record</button></div></form><div class="card card-body"><table class="table"><thead><tr><th>Title</th><th>Type</th><th>Status</th><th>Keywords</th><th>Updated</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$e($r['title'])?></td><td><?=$e($r['content_type'])?></td><td><?=$e($r['status'])?></td><td><?=$e($r['keywords'])?></td><td><?=$e($r['updated_at'])?></td></tr><?php endforeach;?></tbody></table></div></main></body></html>